// Deterministic classic runtime bundle; original pure/store modules remain separate/testable.
import fs from 'node:fs';
const root = new URL('../', import.meta.url);
const modules = [
  ['core', 'metrics-core.mjs', ''],
  ['store', 'metrics-store.mjs', 'const {ENGINE_VERSION, DEFAULT_REGISTRY, createRegistry, metricPeriod, validDate, koreaDate, calculateMonth}=core;'],
  ['dashboard', 'dashboard-runtime.mjs', 'const {DEFAULT_REGISTRY, calculateMonth, compareMetric, resolveGoal, previousMonth, koreaDate}=core; const {createMetricsStore, prepareSnapshot}=store;']
];
const parts = modules.map(([name, file, dependencies]) => {
  const source = fs.readFileSync(new URL('data-hub/' + file, root), 'utf8');
  const exports = [...source.matchAll(/export (?:async )?(?:function|const) (\w+)/g)].map(match => match[1]);
  const body = source.replace(/^import .*;\r?\n/gm, '').replace(/export /g, '');
  return `const ${name}=(()=>{\n${dependencies}\n${body}\nreturn Object.freeze({${exports.join(',')}});\n})();`;
});
const bundle = `// Generated by scripts/hani-data-hub-bundle.mjs. Do not edit directly.\n(()=>{\n'use strict';\n${parts.join('\n')}\nwindow.HANI_DATA_HUB=Object.freeze({...dashboard});\n})();\n`;
const target = new URL('hani-data-hub-v1.js', root);
if (process.argv.includes('--check')) {
  if (fs.readFileSync(target, 'utf8') !== bundle) throw new Error('STALE_DATA_HUB_BUNDLE');
} else fs.writeFileSync(target, bundle);
